  ($g2872$abcd_21_nouns$g2872$, $g2873$abcd$g2873$, $g2874$intermediate$g2874$, $g2875${"id":"abcd_21_nouns","level":"intermediate","q":"21. It's late. Let's go ______.","options":["A) to home","B) at home","C) home","D) to the home"],"correct":2,"explanation":"Home вживається без прийменника to й без артикля."}$g2875$, 12),
  ($g2876$abcd_22_nouns$g2876$, $g2877$abcd$g2877$, $g2878$intermediate$g2878$, $g2879${"id":"abcd_22_nouns","level":"intermediate","q":"22. I'm afraid of ______. They're everywhere in summer.","options":["A) the spiders","B) spiders","C) a spiders","D) spider"],"correct":1,"explanation":"Загальне поняття у множині — без артикля."}$g2879$, 13),
  ($g2880$abcd_23_nouns$g2880$, $g2881$abcd$g2881$, $g2882$intermediate$g2882$, $g2883${"id":"abcd_23_nouns","level":"intermediate","q":"23. ______ accept credit cards nowadays.","options":["A) The most shops","B) Most of shops","C) Most shops","D) The most of shops"],"correct":2,"explanation":"Most + іменник вживається без артикля."}$g2883$, 14),
  ($g2884$abcd_24_nouns$g2884$, $g2885$abcd$g2885$, $g2886$advanced$g2886$, $g2887${"id":"abcd_24_nouns","level":"advanced","q":"24. We took ______ to the zoo last Saturday.","options":["A) children","B) the children","C) a children","D) child"],"correct":1,"explanation":"Йдеться про конкретних дітей, тому the."}$g2887$, 15),
  ($g2888$abcd_25_nouns$g2888$, $g2889$abcd$g2889$, $g2890$intermediate$g2890$, $g2891${"id":"abcd_25_nouns","level":"intermediate","q":"25. Last year I visited Mexico and ______.","options":["A) United States","B) a United States","C) the United States","D) United State"],"correct":2,"explanation":"Назви зі словом States вживаються з the."}$g2891$, 16),
  ($g2892$abcd_26_nouns$g2892$, $g2893$abcd$g2893$, $g2894$intermediate$g2894$, $g2895${"id":"abcd_26_nouns","level":"intermediate","q":"26. ______ is the longest river in Africa.","options":["A) Nile","B) A Nile","C) The Nile","D) The river Nile's"],"correct":2,"explanation":"Назви річок — з the."}$g2895$, 17),
  ($g2896$abcd_27_nouns$g2896$, $g2897$abcd$g2897$, $g2898$intermediate$g2898$, $g2899${"id":"abcd_27_nouns","level":"intermediate","q":"27. They're going skiing in ______ next winter.","options":["A) Alps","B) the Alps","C) an Alps","D) Alp"],"correct":1,"explanation":"Гірські пасма у множині — з the."}$g2899$, 18),
  ($g2900$abcd_28_nouns$g2900$, $g2901$abcd$g2901$, $g2902$advanced$g2902$, $g2903${"id":"abcd_28_nouns","level":"advanced","q":"28. We climbed ______ when we were in Tanzania.","options":["A) the Kilimanjaro","B) a Kilimanjaro","C) Kilimanjaro","D) the Mount the Kilimanjaro"],"correct":2,"explanation":"Окремі гори вживаються без артикля."}$g2903$, 19),
  ($g2904$abcd_29_nouns$g2904$, $g2905$abcd$g2905$, $g2906$advanced$g2906$, $g2907${"id":"abcd_29_nouns","level":"advanced","q":"29. I'd love to visit ______ when I'm in China.","options":["A) Great Wall","B) a Great Wall","C) the Great Wall","D) Great Wall's"],"correct":2,"explanation":"Назви з of (the Great Wall of China) та пам'ятки такого типу — з the."}$g2907$, 20),
  ($g2908$abcd_30_nouns$g2908$, $g2909$abcd$g2909$, $g2910$intermediate$g2910$, $g2911${"id":"abcd_30_nouns","level":"intermediate","q":"30. We're flying from ______ tomorrow morning.","options":["A) the Manchester Airport","B) Manchester Airport","C) a Manchester Airport","D) the airport Manchester"],"correct":1,"explanation":"Назва міста + Airport — без артикля."}$g2911$, 21),
  ($g2912$abcd_31_nouns$g2912$, $g2913$abcd$g2913$, $g2914$advanced$g2914$, $g2915${"id":"abcd_31_nouns","level":"advanced","q":"31. Andy used to work for ______, but now he works for ______.","options":["A) the IBM, the Sony","B) IBM, Sony","C) an IBM, a Sony","D) the IBM, Sony"],"correct":1,"explanation":"Назви компаній вживаються без артикля."}$g2915$, 22),
  ($g2916$abcd_32_nouns$g2916$, $g2917$abcd$g2917$, $g2918$advanced$g2918$, $g2919${"id":"abcd_32_nouns","level":"advanced","q":"32. 'Which newspaper do you want?' '______, please.'","options":["A) Times","B) A Times","C) The Times","D) Time's"],"correct":2,"explanation":"Назви газет вживаються з the."}$g2919$, 23),
  ($g2920$abcd_33_nouns$g2920$, $g2921$abcd$g2921$, $g2922$advanced$g2922$, $g2923${"id":"abcd_33_nouns","level":"advanced","q":"33. He studies at ______, and his sister studies at ______.","options":["A) the Cambridge University, University of Cambridge","B) Cambridge University, the University of Cambridge","C) a Cambridge University, a University of Cambridge","D) the Cambridge University, the University Cambridge"],"correct":1,"explanation":"X University — без артикля, але University of X — з the."}$g2923$, 24)
) as v(lid, type, level, payload, pos)
on conflict (legacy_id) where student_id is null do update set
  type = excluded.type, level = excluded.level,
  payload = excluded.payload, position = excluded.position;

commit;

-- Контроль: очікуємо 11 блоків теорії і 410 вправ
select
  (select count(*) from public.theory_blocks tb join public.topics t on t.id = tb.topic_id
    where t.slug = $g2931$articles$g2931$) as theory_blocks,
  (select count(*) from public.exercises e join public.topics t on t.id = e.topic_id
    where t.slug = $g2932$articles$g2932$ and e.student_id is null) as exercises;
